"""Migrated case_lifecycle workflow for the modern platform."""

from __future__ import annotations


def _value(record: dict, field: str) -> str:
    """Return a field value using legacy empty-string semantics for missing values."""
    value = record.get(field, "")
    return "" if value is None else str(value)


def _nvl(value: str, default: str) -> str:
    """Legacy NVL: empty and missing values use the supplied default."""
    return default if value == "" else value


def fire(state: str, event: str, record: dict) -> dict:
    """Dispatch one explicit case_lifecycle workflow event.

    The input record is never mutated.
    """
    result_record = dict(record)

    matched_transition = None

    if state == "N" and event == "assign":
        if _value(result_record, "OWNER_UID") != "":
            matched_transition = ("A", (("audit", "CASE_ASSIGN"),))

    elif state == "N" and event == "auto_escalate":
        matched_transition = (
            "A",
            (
                ("set", "ESC_FLG", "Y"),
                ("set_nvl", "SEV_CD", "SEV_CD", "3"),
                ("audit", "CASE_ESC"),
                ("notify", "escalation"),
            ),
        )

    elif state == "A" and event == "auto_escalate":
        if _value(result_record, "ESC_FLG") != "Y":
            matched_transition = (
                "A",
                (
                    ("set", "ESC_FLG", "Y"),
                    ("audit", "CASE_ESC"),
                    ("notify", "escalation"),
                ),
            )

    elif state == "A" and event == "await_customer":
        matched_transition = ("P", (("audit", "CASE_PEND"),))

    elif state == "P" and event == "customer_reply":
        matched_transition = ("A", ())

    elif state == "A" and event == "resolve":
        if _value(result_record, "RES_DT") != "00000000":
            matched_transition = ("R", (("audit", "CASE_RES"),))

    elif state == "R" and event == "close":
        matched_transition = ("X", (("audit", "CASE_CLOSE"),))

    elif state == "R" and event == "reopen":
        matched_transition = (
            "A",
            (
                ("set", "RES_DT", "00000000"),
                ("audit", "CASE_REOPEN"),
            ),
        )

    if matched_transition is None:
        return {
            "state": state,
            "record": result_record,
            "audits": ["WF_NOMATCH"],
            "notifies": [],
            "matched": False,
        }

    next_state, actions = matched_transition
    audits: list[str] = []
    notifies: list[str] = []

    for action in actions:
        kind = action[0]
        if kind == "set":
            _, field, value = action
            result_record[field] = value
        elif kind == "set_nvl":
            _, field, source_field, default = action
            result_record[field] = _nvl(_value(result_record, source_field), default)
        elif kind == "audit":
            audits.append(action[1])
        elif kind == "notify":
            notifies.append(action[1])

    return {
        "state": next_state,
        "record": result_record,
        "audits": audits,
        "notifies": notifies,
        "matched": True,
    }
